export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const apexTime = u / g;
  const apexHeight = (u * u) / (2 * g);
  const t = Math.min(Math.max(0, time), 2 * apexTime);

  const height = u * t - 0.5 * g * t * yPositive(t, u, g);
  const velocity = u - g * t;
  const acceleration = -g;
  const force = m * g;

  let motionState = "Rising";
  if (t === 0) motionState = "Ready to toss";
  else if (Math.abs(t - apexTime) < 0.02) motionState = "At the top";
  else if (t > apexTime && height > 0) motionState = "Falling";
  else if (height <= 0 && t > 0) motionState = "Back at launch height";

  const objects = [];

  objects.push(...sdk.panel({ id: "lane.left", x: 20, y: 20, w: 280, h: 360, title: "The Motion", state: motionState }));
  objects.push(sdk.axis("axis.height", { x: 50, y: 340, length: 280, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));

  const ballY = 340 - (height / 2.2) * 280;
  objects.push(sdk.circle("ball.toss", 160, ballY, 24, { role: "observed" }));

  objects.push(...sdk.vector("vec.v", { x: 185, y: ballY }, { value: velocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a", { x: 215, y: ballY }, { value: acceleration, direction: "up" }, { scale: 15, label: "a" }));

  objects.push(sdk.callout(235, ballY - 20, [
    `v: ${velocity.toFixed(2)} m/s`,
    `a: ${acceleration.toFixed(1)} m/s^2`,
    `Fg: ${force.toFixed(1)} N`
  ], { id: "callout.toss" }));

  objects.push(...sdk.panel({ id: "lane.right", x: 320, y: 20, w: 300, h: 360, title: "Velocity over Time", state: `t = ${t.toFixed(2)} s` }));

  const duration = 2 * apexTime;
  const points = [];
  const steps = 20;
  for (let i = 0; i <= steps; i++) {
    const st = (i / steps) * duration;
    const sv = u - g * st;
    const sx = 350 + (st / 1.8) * 240;
    const sy = 240 - (sv / 5.5) * 100;
    points.push([sx, sy]);
  }

  objects.push(sdk.polyline("plot.vt.trace", points, { role: "observed" }));

  const curX = 350 + (t / 1.8) * 240;
  const curY = 240 - (velocity / 5.5) * 100;
  objects.push(sdk.circle("plot.vt.marker", curX, curY, 8, { role: "prediction" }));

  objects.push(sdk.text("plot.vt.note", 350, 340, "Slope a = -g", { align: "start" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: Number(velocity.toFixed(2)) },
        { id: "acceleration", value: Number(acceleration.toFixed(1)) },
        { id: "force", value: Number(force.toFixed(1)) },
        { id: "motionState", value: motionState }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime,
      apexHeight,
      height,
      velocity,
      acceleration,
      force
    }
  };
}

function yPositive(t, u, g) {
  return t;
}
